/* ── TOC ── */
    .toc { background:var(--off-white); border:1px solid var(--rule-strong); border-radius:10px; padding:1.1rem 1.4rem; margin:1.8rem 0 0; }

    .toc ol { margin:0; padding-left:0.5rem; display:flex; flex-direction:column; gap:0.28rem; }
    .toc li { font-size:0.855rem; color:var(--ink-soft); }
    .toc a { color:var(--unit-ink); text-decoration:none; }
    .toc a:hover { text-decoration:underline; }

.fig-hdr { display:flex; align-items:baseline; gap:0.75rem; margin-bottom:0.5rem; }
.fig-label { font-family:var(--font-mono); font-size:0.7rem; font-weight:600; letter-spacing: normal; text-transform: none; color:var(--unit-ink); background:var(--accent-light); padding:3px 8px; border-radius:4px; }
.fig-title { font-size:1.25rem; font-weight:600; color:var(--text); }

/* ── canvas wrapper ── */

canvas { display:block; width:100%; height:320px; cursor:default; }

/* Fig 4.8 three-panel market-demand builder. Widened to the page's wide band
   (via .bleed-wide) so each panel has room; stacks to one readable column on
   narrow screens instead of staying three cramped columns. */
.md-panels { display:grid; grid-template-columns:repeat(3,1fr); gap:0.6rem; }
@media (max-width:820px) {
  .md-panels { grid-template-columns:1fr; gap:0.9rem; }
  .md-panels > .fig-plot { max-width:480px; margin-left:auto; margin-right:auto; width:100%; }
}

/* ── canvas + D3 SVG label overlay ── */
.cvs-stack { position:relative; }
.cvs-stack > canvas { position:relative; z-index:1; }
.cvs-overlay { position:absolute; top:0; left:0; width:100%; height:100%; z-index:2; pointer-events:none; }

.verdict { font-weight:600; font-size:0.9rem; margin-top:0.5rem; }
.verdict.elastic { color:var(--d-second); }
.verdict.unit { color:#5f6875; }
.verdict.inelastic { color:#14568c; }
